<?php
declare(strict_types=1);
$preview=isset($_GET['preview']);
if($preview){require_once __DIR__.'/../auth_check.php';if(!hasPermission('acces_admin')){http_response_code(403);exit('Accès refusé');}}
require_once __DIR__.'/../model/Database.php';
require_once __DIR__.'/../model/CompanyBranding.php';
require_once __DIR__.'/SiteContent.php';
header('Cache-Control: no-store');header('X-Content-Type-Options: nosniff');
$db=Database::getConnection();$brand=CompanyBranding::get($db);
try{$row=SiteContent::read($db);}catch(PDOException $e){$row=[];}
$json=$row[$preview?'draft_json':'published_json']??null;$initialDemo=empty($row);$available=$preview||$initialDemo||!empty($json);
$data=($preview||$initialDemo)&&empty($json)?BtpDemo::content($brand):SiteContent::decode($json,$brand);$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$logo=CompanyBranding::logoUrl('../',$db);$icon=CompanyBranding::iconUrl('../',$db);
$media=static fn($id)=>BtpDemo::photo($id)??('media.php?id='.rawurlencode($id).($preview?'&preview=1':''));
$sections=['about'=>'À propos','services'=>'Nos activités','projects'=>'Nos réalisations','values'=>'Nos engagements','news'=>'Actualités','partners'=>'Clients et partenaires','careers'=>'Carrières','credentials'=>'Diplômes et certifications','awards'=>'Trophées et distinctions'];
$page=(string)($_GET['page']??'home');$detail=isset($_GET['item'])?(int)$_GET['item']:null;
if(!$available)$page='home';
if($detail!==null&&(!isset($data[$page])||!is_array($data[$page])||!isset($data[$page][$detail]))){http_response_code(404);$detail=null;}
if($page!=='home'&&!isset($sections[$page])&&!in_array($page,['contact','legal','privacy'],true)){http_response_code(404);$page='home';}
$url=static fn($page='home',$item=null)=>'public.php?'.http_build_query(array_filter(['page'=>$page,'item'=>$item,'preview'=>$preview?1:null],static fn($v)=>$v!==null));
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$h($available?($data['seo_title']?:$brand['company_name']):'Site en préparation')?></title><?php if($preview||!$available||$data['demo']):?><meta name="robots" content="noindex,nofollow"><?php else:?><meta name="description" content="<?=$h($data['seo_description'])?>"><?php endif;?><?php if($icon):?><link rel="icon" href="<?=$h($icon)?>"><?php endif;?><link rel="stylesheet" href="../branding_theme.php"><link rel="stylesheet" href="site.css"></head><body class="public-site"><?php if($preview):?><div class="preview-banner">Aperçu privé du brouillon · <a href="index.php">Retour au studio</a></div><?php endif;?>
<?php if($available&&$data['demo']):?><div class="preview-banner">Site de démonstration BTP · Illustrations et références fictives à personnaliser</div><?php endif;?><header class="public-nav"><div class="public-inner nav-inner"><a class="public-brand" href="<?=$h($url())?>"><?php if($logo):?><img src="<?=$h($logo)?>" alt=""><?php endif;?><strong><?=$h($brand['company_name'])?></strong></a><?php if($available):?><nav aria-label="Navigation"><?php foreach($sections as $key=>$label):if(empty($data[$key]))continue;?><a href="<?=$h($url($key))?>"><?=$h($label)?></a><?php endforeach;?><?php if($data['show_contact']||$data['contact_form']):?><a href="<?=$h($url('contact'))?>">Contact</a><?php endif;?></nav><?php endif;?></div></header>
<main id="accueil"><?php if($page==='home'):?><section class="hero premium-hero"><?php if($available&&$data['hero_image']):?><img class="hero-photo" src="<?=$h($media($data['hero_image']))?>" alt=""><?php endif;?><div class="public-inner hero-content"><span class="kicker"><?=$h($available&&$data['tagline']?$data['tagline']:$brand['company_name'])?></span><h1><?=$h($available?$data['headline']:'Notre site est en préparation')?></h1><p><?=$h($available?$data['intro']:'Nous vous invitons à revenir prochainement.')?></p><div class="hero-actions"><?php if($available&&($data['show_contact']||$data['contact_form'])):?><a class="button accent" href="<?=$h($url('contact'))?>">Parlons de votre projet <span aria-hidden="true">↗</span></a><?php endif;?><?php if($available&&$data['services']):?><a class="button hero-secondary" href="<?=$h($url('services'))?>">Découvrir nos activités</a><?php endif;?></div></div><div class="hero-decoration" aria-hidden="true"></div><?php if($available&&$data['slides']):?><div class="slide-controls" aria-label="Diapositives"><?php foreach($data['slides'] as $slide):?><button type="button" data-slide-title="<?=$h($slide['title'])?>" data-slide-body="<?=$h($slide['body'])?>" data-slide-image="<?=$h(!empty($slide['image'])?$media($slide['image']):'')?>"><?=$h($slide['title'])?></button><?php endforeach;?></div><?php endif;?></section><?php else:?><section class="page-hero"><div class="public-inner"><a href="<?=$h($url())?>">Accueil</a> / <?=$h($sections[$page]??(['legal'=>'Mentions légales','privacy'=>'Confidentialité'][$page]??'Contact'))?><h1><?=$h($sections[$page]??(['legal'=>'Mentions légales','privacy'=>'Confidentialité'][$page]??'Contact'))?></h1></div></section><?php endif;?>
<?php if($available):?>
<?php if(in_array($page,['legal','privacy'],true)):?><section class="public-section"><div class="public-inner"><p class="prose"><?=nl2br($h($data[$page]))?></p></div></section><?php endif;?>
<?php if($page==='home'&&$data['figures']):?><section class="figure-band"><div class="public-inner figure-grid"><?php foreach($data['figures'] as $item):?><div><strong><?=$h($item['title'])?></strong><span><?=$h($item['body'])?></span></div><?php endforeach;?></div></section><?php endif;?>
<?php foreach($sections as $key=>$label):if(empty($data[$key])||($page!=='home'&&$page!==$key))continue;?><section class="public-section section-<?=$key?>" id="<?=$key?>"><div class="public-inner"><div class="section-heading"><span class="section-kicker"><?=$h($brand['company_name'])?> / <?=$h($label)?></span><h2><?=$h($label)?></h2></div><?php if($key==='about'):?><div class="about-grid"><div><p class="prose"><?=nl2br($h($data[$key]))?></p></div><?php if($data['about_image']):?><img class="about-photo" src="<?=$h($media($data['about_image']))?>" alt="Présentation de l’entreprise" loading="lazy"><?php endif;?></div><?php else:?><div class="public-grid"><?php foreach($data[$key] as $i=>$item):if($detail!==null&&$page===$key&&$detail!==$i)continue;?><article><?php if(!empty($item['image'])):?><img class="entry-photo" loading="lazy" src="<?=$h($media($item['image']))?>" alt="<?=$h($item['title'])?>"><?php endif;?><span class="card-index"><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><h3><?=$h($item['title'])?></h3><p><?=$h($detail!==null?$item['body']:mb_strimwidth($item['body'],0,240,'…'))?></p><?php if(!empty($item['category'])||!empty($item['location'])):?><p class="entry-meta"><?=$h(trim(($item['category']??'').' · '.($item['location']??''),' ·'))?></p><?php endif;?><?php if($detail===null):?><a class="entry-link" href="<?=$h($url($key,$i))?>">En savoir plus →</a><?php else:?><a class="entry-link" href="<?=$h($url($key))?>">Retour à la rubrique</a><?php endif;?></article><?php endforeach;?></div><?php endif;?></div></section><?php endforeach;?>
<?php if(($data['show_contact']||$data['contact_form'])&&in_array($page,['home','contact'],true)):?><section id="contact" class="contact"><div class="public-inner contact-grid"><div><span class="kicker">Entrons en relation</span><h2>Parlons de votre projet.</h2><p>Retrouvez les coordonnées de notre entreprise.</p></div><div><?php foreach(($data['show_contact']?['address'=>'Adresse','phone'=>'Téléphone','email'=>'Email']:[]) as $key=>$label):if(empty($brand[$key]))continue;?><p><strong><?=$label?></strong><br><?php if($key==='email'&&filter_var($brand[$key],FILTER_VALIDATE_EMAIL)):?><a href="mailto:<?=$h($brand[$key])?>"><?=$h($brand[$key])?></a><?php elseif($key==='phone'&&preg_match('/^\+?[0-9 ()-]+$/D',$brand[$key])):?><a href="tel:<?=$h(preg_replace('/[^0-9+]/','',$brand[$key]))?>"><?=$h($brand[$key])?></a><?php else:?><?=$h($brand[$key])?><?php endif;?></p><?php endforeach;?><?php if($data['contact_form']):?><form class="public-form" method="post" action="contact.php"><h3>Demande de devis ou de renseignements</h3><label>Nom / entreprise<input name="name" required maxlength="190"></label><label>Email<input name="email" type="email" required maxlength="190"></label><label>Téléphone<input name="phone" maxlength="80"></label><label>Objet<input name="subject" required maxlength="190"></label><label>Votre projet<textarea name="message" required maxlength="5000" rows="5"></textarea></label><div hidden><label>Site<input name="website" tabindex="-1" autocomplete="off"></label></div><p>Les informations sont transmises à l’entreprise pour répondre à votre demande.</p><button class="button accent" <?=($preview||$initialDemo)?'disabled':''?>>Envoyer la demande</button></form><?php endif;?></div></div></section><?php endif;?><?php endif;?></main><?php require __DIR__.'/public_footer.php';?><script src="public.js?v=2" defer></script></body></html>